/** JSON-RPC 2.0 request envelope (server → IDE peer). */
export interface JsonRpcRequest {
  jsonrpc: "2.0";
  id: string;
  method: string;
  params?: unknown;
}

/** JSON-RPC 2.0 success response (IDE peer → server). */
export interface JsonRpcSuccess {
  jsonrpc: "2.0";
  id: string;
  result: unknown;
}

/** JSON-RPC 2.0 error response (IDE peer → server). */
export interface JsonRpcError {
  jsonrpc: "2.0";
  id: string;
  error: {
    code: number;
    message: string;
    data?: unknown;
  };
}

export type JsonRpcResponse = JsonRpcSuccess | JsonRpcError;

/** Methods the server can push to the IDE peer as fire-and-forget notifications. */
export type IdeNotificationMethod =
  | "connected"
  | "tool.fallback"
  | "approval.pending"
  | "run.status";

/**
 * JSON-RPC 2.0 notification (server → IDE peer). Notifications have no `id`
 * and never receive a response; they are best-effort wake-ups.
 */
export interface JsonRpcNotification {
  jsonrpc: "2.0";
  method: IdeNotificationMethod;
  params?: unknown;
}

export function isJsonRpcNotification(value: unknown): value is JsonRpcNotification {
  if (!value || typeof value !== "object") return false;
  const record = value as Record<string, unknown>;
  return (
    record.jsonrpc === "2.0"
    && typeof record.method === "string"
    && !("id" in record)
  );
}

export function isJsonRpcResponse(value: unknown): value is JsonRpcResponse {
  if (!value || typeof value !== "object") return false;
  const record = value as Record<string, unknown>;
  return record.jsonrpc === "2.0" && typeof record.id === "string";
}

export function isJsonRpcRequest(value: unknown): value is JsonRpcRequest {
  if (!value || typeof value !== "object") return false;
  const record = value as Record<string, unknown>;
  return (
    record.jsonrpc === "2.0"
    && typeof record.id === "string"
    && typeof record.method === "string"
  );
}

