import { z } from "zod";

export const handoffPayloadKindSchema = z.enum([
  "PlanSpec",
  "Findings",
  "Patch",
  "VerificationReport",
  "Summary",
  "Generic",
  "TestReport",
  "ResearchFinding",
]);

const baseHandoff = z.object({
  kind: handoffPayloadKindSchema,
  summary: z.string().optional(),
});

export const planSpecHandoffSchema = baseHandoff.extend({
  kind: z.literal("PlanSpec"),
  steps: z.array(z.object({
    id: z.string(),
    description: z.string(),
    nodeTypeHint: z.string().optional(),
  })),
  rationale: z.string().optional(),
  tracks: z.array(z.object({
    title: z.string(),
    body: z.string().optional(),
  })).optional(),
  // Structured planning lists (optional for back-compat with older planners).
  // `dependsOn` + `blocking` make non-blocking features explicit: a feature with
  // no unmet dependency and `blocking !== true` is eligible for parallel execution.
  features: z.array(z.object({
    id: z.string(),
    title: z.string(),
    description: z.string().optional(),
    dependsOn: z.array(z.string()).optional(),
    blocking: z.boolean().optional(),
    docsRequired: z.boolean().optional(),
  })).optional(),
  documentation: z.array(z.object({
    id: z.string(),
    title: z.string(),
    target: z.string().optional(),
    featureId: z.string().optional(),
  })).optional(),
  blockers: z.array(z.object({
    id: z.string(),
    title: z.string(),
    severity: z.enum(["hard", "soft"]),
    detail: z.string().optional(),
    blocksFeatureIds: z.array(z.string()).optional(),
  })).optional(),
});

export const findingsHandoffSchema = baseHandoff.extend({
  kind: z.literal("Findings"),
  findings: z.array(z.object({
    title: z.string(),
    body: z.string().optional(),
    source: z.string().optional(),
  })),
});

export const patchHandoffSchema = baseHandoff.extend({
  kind: z.literal("Patch"),
  files: z.array(z.object({
    path: z.string(),
    diff: z.string().optional(),
    sizeBytes: z.number().optional(),
  })),
});

export const verificationReportHandoffSchema = baseHandoff.extend({
  kind: z.literal("VerificationReport"),
  passed: z.boolean(),
  stages: z.array(z.object({
    stageId: z.string(),
    passed: z.boolean(),
    details: z.string().optional(),
  })),
});

export const summaryHandoffSchema = baseHandoff.extend({
  kind: z.literal("Summary"),
  body: z.string(),
});

export const genericHandoffSchema = baseHandoff.extend({
  kind: z.literal("Generic"),
  data: z.record(z.string(), z.unknown()),
});

export const testReportHandoffSchema = baseHandoff.extend({
  kind: z.literal("TestReport"),
  passed: z.boolean(),
  failures: z.array(z.object({
    test: z.string(),
    message: z.string().optional(),
  })).default([]),
});

export const researchFindingHandoffSchema = baseHandoff.extend({
  kind: z.literal("ResearchFinding"),
  tracks: z.array(z.object({
    title: z.string(),
    body: z.string().optional(),
    source: z.string().optional(),
  })),
});

export const handoffPayloadSchema = z.discriminatedUnion("kind", [
  planSpecHandoffSchema,
  findingsHandoffSchema,
  patchHandoffSchema,
  verificationReportHandoffSchema,
  summaryHandoffSchema,
  genericHandoffSchema,
  testReportHandoffSchema,
  researchFindingHandoffSchema,
]);

export type HandoffPayloadInput = z.infer<typeof handoffPayloadSchema>;
